#!/bin/sh
# SPDX-License-Identifier: GPL-3.0-only
# Distribution file: install-odr.sh (includes the static AArch64 writer).
set -eu
set -f
PATH=/usr/sbin:/usr/bin:/sbin:/bin; LC_ALL=C; export PATH LC_ALL
umask 077
die() { printf 'Error: %s\n' "$*" >&2; exit 1; }
usage() {
	cat <<'HELP'
Install Open Dream Rescue from the running Dreambox One or Two image.
  sh install-odr.sh [--check | --yes] [--backup-dir DIRECTORY] [--odr-only]
Default: check downloads, show the plan and ask before installing.
--check       Download and check only. Do not program either device.
--yes         Apply the checked plan without an interactive prompt.
--backup-dir  Save the complete old recovery partition here (default:
              /home/root/odr-backups). A mounted USB directory also works.
--odr-only    Install rescue without updating the front processor.
The installer also accepts a download piped to sh. Run as root in the installed image.
It asks for confirmation in your terminal and leaves the receiver running.
HELP
}
compare_versions() {
	awk -v a="$1" -v b="$2" 'BEGIN {
		if(a!~/^[0-9]+\.[0-9]+$/ || b!~/^[0-9]+\.[0-9]+$/ || length(a)>9 || length(b)>9) exit 1
		split(a,x,"[.]");split(b,y,"[.]");
		print (x[1]+0<y[1]+0 || (x[1]+0==y[1]+0 && x[2]+0<y[2]+0))?"update":"keep"
	}'
}
base=https://raw.githubusercontent.com/oe-alliance/bootmenu/master
transfer() (
	# A file-size limit also applies to old wget (including responses
	# without Content-Length). The exact final length is checked separately.
	# Leave one block for tools that probe EOF with copy_file_range.
	# The caller verifies the exact size and hash before installation.
	ulimit -f "$(( $3 / 512 + 1 ))" || exit 1
	url_arg=$1; out_arg=$2; limit_arg=$3; trust_arg=$4
	if command -v curl >/dev/null 2>&1; then
		set --
		if [ "$trust_arg" = pinned ]; then set -- -k; fi
		curl -q "$@" -fLsS --proto '=https' --proto-redir '=https' --connect-timeout 12 --max-time 300 --max-filesize "$limit_arg" -o "$out_arg" "$url_arg" && exit 0
		# Older curl versions lack some of those options. A pinned file may
		# also be fetched directly from the raw URL without redirects.
		if [ "$trust_arg" = pinned ]; then
			curl -q -kfsS --max-time 300 -o "$out_arg" "$url_arg" && exit 0
		fi
	fi
	command -v wget >/dev/null 2>&1 || exit 1
	if [ "$trust_arg" = verified ]; then
		# Some embedded wget builds never verify a certificate. Do not treat
		# their catalogue as a trust source for an unpinned future release.
		wget --version 2>/dev/null | grep -q 'GNU Wget' || exit 1
		wget -e check_certificate=on --max-redirect=0 -T 45 -O "$out_arg" "$url_arg"
	else
		wget --no-check-certificate -T 45 -O "$out_arg" "$url_arg" || wget -O "$out_arg" "$url_arg"
	fi
)
catalogue() {
	trust=verified
	if ! transfer "$base/dream$model/$1" "$tmp/list" 16384 verified; then
		trust=pinned
		transfer "$base/dream$model/$1" "$tmp/list" 16384 pinned || die "Cannot download dream$model/$1 from GitHub. Check network, DNS, date and HTTPS support in this image."
	fi
	[ "$(wc -c < "$tmp/list")" -le 16384 ] || die "Catalogue too large"
	awk -v kind="$2" '{
		sub(/\r$/,""); if($0~/^[[:space:]]*(#|$)/)next
		if(NF!=5 || ($1!=kind && !(kind=="frontprocessor" && $1=="bootloader")))bad=1
		if($1!=kind)next
		if(++n!=1 || $2!~/^[a-zA-Z0-9._-]+$/ || length($2)>31 || $3!~/^[1-9][0-9]*$/ || length($3)>8 || $3+0<1024 ||
		   $3+0>(kind=="rescue"?33554432:2097152) || length($4)!=64 || $4!~/^[0-9a-f]+$/ ||
		   $5!~/^https:\/\/raw\.githubusercontent\.com\/oe-alliance\/bootmenu\/[A-Za-z0-9._\/-]+$/)bad=1
		print $2, $3, $4, $5
	} END {if(n!=1 || bad)exit 1}' "$tmp/list" > "$tmp/entry" || die "Invalid or ambiguous $2 catalogue"
	IFS=' ' read -r version bytes digest url < "$tmp/entry" || die "Cannot read $2 catalogue"
}
payload() {
	# Even with expired system CAs, a digest known independently of the
	# network remains usable. Future rescue releases need verified HTTPS.
	if [ "$trust" = pinned ] && [ "$digest" != "$2" ] && [ "$digest" != "${3:-}" ] && [ "$digest" != "${4:-}" ] && [ "$digest" != "${5:-}" ]; then
		die "This release is not pinned for this model. Use a matching installer or a verified online catalogue."
	fi
	if ! transfer "$url" "$1" "$bytes" verified; then
		# The expected digest is now either locally pinned or authenticated.
		transfer "$url" "$1" "$bytes" pinned || die "Cannot download $url. Check network, DNS, date and HTTPS support in this image."
	fi
	[ "$(wc -c < "$1")" -eq "$bytes" ] || die "Downloaded payload has the wrong size"
	actual=$(sha256sum "$1") || die "Cannot hash the downloaded file"
	[ "${actual%% *}" = "$digest" ] || die "Downloaded payload has the wrong SHA-256"
}
confirm_plan() {
	printf 'Apply this plan? [y/N] '
	# With wget | sh, only the terminal can supply the user's response.
	case ${0##*/} in
		sh|ash|dash|bash|-sh|-ash|-dash|-bash) IFS= read -r answer </dev/tty || answer= ;;
		*) IFS= read -r answer || answer= ;;
	esac
	case "$answer" in y|Y|yes|YES) return 0 ;; *) return 1 ;; esac
}
main() {
	mode=ask; fp=yes; backup=/home/root/odr-backups
	while [ "$#" -gt 0 ]; do
		case "$1" in
			--help|-h) usage; exit 0 ;;
			--check|--yes) [ "$mode" = ask ] || die 'Choose only one of --check and --yes'; mode=${1#--} ;;
			--odr-only) fp=no ;;
			--backup-dir) shift; [ "$#" -gt 0 ] || die '--backup-dir needs an absolute directory'; backup=$1 ;;
			*) die "Unknown option: $1 (see --help)" ;;
		esac
		shift
	done
	case "$backup" in /*) ;; *) die 'Backup directory must be an absolute path' ;; esac
	[ "$(id -u)" = 0 ] || die 'Run as root in the installed Linux image'
	[ ! -e /etc/odr-rescue ] || die 'In ODR use Maintenance > Device firmware instead'
	for tool in sha256sum base64 awk sed mktemp wc; do
		command -v "$tool" >/dev/null 2>&1 || die "Required tool missing from the running image: $tool"
	done
	if ! command -v curl >/dev/null 2>&1 && ! command -v wget >/dev/null 2>&1; then
		die 'Install curl or wget with HTTPS support in the running image.'
	fi
	model=$(cat /proc/stb/info/model) || die 'Cannot read the Dreambox model'
	case "$model" in
		one) v39pin=2405c977980a980ab982a633056f7e5ef71768ba65b795de51277fdc6f3daade
		     v38pin=0912d7dae4820ac59ee8d232367b65db494f4760b2fc6feb6e833e7cbf54797c; nextpin=a541ea7465fd6dfa987ab4718c941a811995db8d94bf48a6057869976ba46e01; pin=c9caee39e793f2fdc21758e47418d43a57ed40af5244f06fc96dffe240a681f4
		     fpver=1.15; fppin=f290ddf205a2f2e18a2b55df6336385fda828bd18a8676b6111fa8ab916ebbd0; fpalt=cdc3043abb9be9fdf81f4a5e06d609735721c6c004555af0a0f82b2e22aafb63 ;;
		two) v39pin=302d3d2b4137baf49dcca7357f8ab46f7d7e96b57805e06d2fc89f5736ce9b4b
		     v38pin=d4bd16b6443d01b9c506a896d2f1cb08b0d5ef83c6610d12d87b8f00b16dde34; nextpin=33396dc9d73f2898f507a731fbd1d5bcf6957e33bc742c169621f1bb4ea4bc0e; pin=05b8e83429f0f5a338f65b56f49d518ab8f84d829b94ab30bbf5e71c7941198e
		     fpver=1.14; fppin=5e379805f4961b69cd549e2d5742d97115409a93fb2e25800c0ef24022c14ce5; fpalt=7dac304e7bed79438ca6935693533386f1759e41df8406621d46b84b6ebb1c0c ;;
		*) die "Unsupported receiver: $model";;
	esac
	cid=$(cat /sys/block/mmcblk0/device/cid) || die 'Cannot identify the internal eMMC'
	mkdir /run/odr-image-install.lock || die 'Another installer is active (a reboot clears a stale lock)'
	tmp=
	trap 'if [ -n "$tmp" ]; then rm -f "$tmp/helper" "$tmp/odr" "$tmp/front.hex" "$tmp/list" "$tmp/entry"; rmdir "$tmp" || :; fi; rmdir /run/odr-image-install.lock || :' EXIT
	trap 'exit 1' HUP INT TERM
	tmp=$(mktemp -d /tmp/odr-install.XXXXXX) || die 'Cannot create private workspace'
	unpack_helper > "$tmp/helper" || die 'Cannot unpack the installer'
	actual=$(sha256sum "$tmp/helper"); [ "${actual%% *}" = '9afe74fbf86f949d2c6d5054b1e163fdf0bfe4a9f2eb4488071fa19788453cf2' ] || die 'Installer is incomplete or damaged'
	chmod 700 "$tmp/helper"; helper=$tmp/helper
	echo "Dreambox $model: checking the online internal rescue release..."
	catalogue rescue rescue
	payload "$tmp/odr" "$pin" "$nextpin" "$v38pin" "$v39pin"
	rescue_size=$bytes; rescue_sha=$digest
	printf 'Rescue: ODR %s (%s bytes)\n' "$version" "$bytes"
	"$helper" check "$model" "$tmp/odr" "$rescue_size" "$rescue_sha" "$cid" || exit 1
	fp_action=skip
	if [ "$fp" = yes ]; then
		current=$(cat /proc/stb/fp/fp_version) || die 'Cannot read the front processor version. Use --odr-only for rescue alone.'
		catalogue firmware frontprocessor
		fp_action=$(compare_versions "$current" "$version") || die 'Unrecognised front processor version; refusing to guess.'
		echo "Front processor: installed $current, offered $version."
		if [ "$fp_action" = update ]; then
			[ "$version" = "$fpver" ] || die 'This front processor release needs a newer installer'
			payload "$tmp/front.hex" "$fppin" "$fpalt"
			"$helper" nrf --check-live "$tmp/front.hex" "$model" || exit 1
		else echo 'Front processor is current or newer; it will not be programmed.'; fi
	else echo 'Front processor skipped (--odr-only).'; fi
	if [ "$mode" = check ]; then echo 'Check complete. No hardware was written.'; return; fi
	printf 'Old rescue backup location if an update is needed: %s\n' "$backup"
	if [ "$fp_action" = update ]; then echo "The front processor will also be updated to $fpver. Keep power connected."; fi
	if [ "$mode" != yes ] && ! confirm_plan; then
		echo 'Cancelled. No hardware was written.'; return
	fi
	mkdir -p "$backup" || die 'Cannot create backup directory; use --backup-dir on mounted USB storage'
	"$helper" apply "$model" "$tmp/odr" "$rescue_size" "$rescue_sha" "$cid" "$backup" || exit 1
	if [ "$fp_action" = update ]; then
		"$helper" nrf --program "$tmp/front.hex" "$model" --confirmed || die 'ODR is installed. Front processor update did not complete; keep power connected and check the reported error.'
	fi
	echo 'Done. Next time you start internal rescue, Open Dream Rescue will run. No reboot requested.'
}
